#include <cassert>
#include <iostream>
#include <map>
#include <vector>
struct Node { int value; int left; int right; };
// active에는 현재 노드 이전 경로의 누적합만 들어 있다.
long long visit(const std::vector<Node>& a, int i, long long prefix, long long target,
                std::map<long long,int>& active) {
    if (i == -1) return 0;
    const Node& n = a[static_cast<std::size_t>(i)];
    const long long sum = prefix + n.value;
    const auto found = active.find(sum - target);
    long long count = found == active.end() ? 0 : found->second;
    ++active[sum];
    count += visit(a,n.left,sum,target,active);
    count += visit(a,n.right,sum,target,active);
    // 형제 가지로 돌아가기 전에 현재 경로의 흔적을 제거한다.
    if (--active[sum] == 0) active.erase(sum);
    return count;
}
long long countPaths(const std::vector<Node>& a, int root, long long target) {
    std::map<long long,int> active; active[0] = 1;
    return visit(a,root,0,target,active);
}
// 독립 기준: 모든 시작점에서 아래로 가는 경로를 직접 열거한다.
long long from(const std::vector<Node>& a, int i, long long sum, long long target) {
    if (i == -1) return 0;
    const Node& n = a[static_cast<std::size_t>(i)]; sum += n.value;
    return (sum == target ? 1LL : 0LL) + from(a,n.left,sum,target) + from(a,n.right,sum,target);
}
long long brute(const std::vector<Node>& a, long long target) {
    long long result = 0;
    for (std::size_t i=0;i<a.size();++i) result += from(a,static_cast<int>(i),0,target);
    return result;
}
int main() {
    const std::vector<std::vector<Node> > shapes = {
        {{0,1,2},{0,3,4},{0,-1,-1},{0,-1,-1},{0,-1,-1}},
        {{0,-1,1},{0,-1,2},{0,-1,3},{0,-1,4},{0,-1,-1}}
    };
    int tested = 0;
    for (const auto& shape : shapes) for(int mask=0;mask<243;++mask) {
        auto a=shape;int x=mask;for(auto& n:a){n.value=x%3-1;x/=3;}
        for(int target=-5;target<=5;++target){assert(countPaths(a,0,target)==brute(a,target));++tested;}
    }
    assert(countPaths({},-1,0)==0);
    assert(countPaths({{0,-1,1},{0,-1,2},{0,-1,-1}},0,0)==6);
    assert(countPaths({{1,1,2},{-1,-1,-1},{-1,-1,-1}},0,0)==2);
    std::cout << "path-sum brute comparisons: " << tested << "; empty/zero/sibling passed\n";
}
